UPDATE governor_races SET 
  dem_candidate = 'TBD — D Primary: Sep 9, 2026 (McKee, Foulkes)',
  notes = 'Dan McKee (D, incumbent) faces Helena Foulkes in the September 9 Democratic primary. Foulkes leads by 20 points in polls. R primary also Sep 9.'
WHERE state_code = 'RI';

UPDATE governor_races SET 
  notes = 'Greg Abbott (R, incumbent) won R primary with 81.8%. Gina Hinojosa (D, state rep) won D primary with 58.5%. General election November 3, 2026. Rated Solid R.'
WHERE state_code = 'TX';

UPDATE governor_races SET
  notes = 'Shapiro (D, incumbent) won uncontested primary May 19. Garrity (R, state treasurer, Trump-endorsed) won uncontested primary May 19. Rated Solid D.'
WHERE state_code = 'PA';

